import os
import json
import requests
from datetime import datetime, timezone

def _hr_get_response():
    # The human form response: per platform docs it is stored in a variable
    # named "decision" with keys is_approved (bool) and reviewer_comment.
    # Check that first, then fall back to other locations defensively.
    candidates = []
    try:
