    return {}

def _hr_decision(resp):
    # Normalize the approval flag. Returns "APPROVED", "REJECTED", or None.
    val = resp.get("is_approved")
    if val is None:
        for k in ("decision", "approval", "action", "choice"):
            v = resp.get(k)
            if isinstance(v, str):
                val = v
                break
    if isinstance(val, bool):
        return "APPROVED" if val else "REJECTED"
    if isinstance(val, str):
        s = val.strip().upper()
        if s in ("TRUE", "APPROVE", "APPROVED", "YES"):
            return "APPROVED"
        if s in ("FALSE", "REJECT", "REJECTED", "NO"):
            return "REJECTED"
    return None

def _hr_comment(resp):
    for k in ("reviewer_comment", "comment", "comments", "rationale"):
        v = resp.get(k)
        if isinstance(v, str) and v.strip():
            return v.strip()
    return None

def step_3b_reject_run():
    step_id = "step_3b_reject"
    resp = _hr_get_response()
    dec = _hr_decision(resp)
    comment = _hr_comment(resp)
    issue_key = user_inputs.get("issue_key")
    repo = user_inputs.get("github_repository")
    token = os.environ.get("GITHUB_TOKEN")
    now = datetime.now(timezone.utc).isoformat()

    payload = {
        "run_status": "FAILED",
        "issue_key": issue_key,
        "decision": "REJECTED_BY_HUMAN",
        "reviewer_comment": comment,
        "github_comment_status": None,
        "github_comment_url": None,
        "label_status": None,
        "timestamps": {
            "escalated_at": globals().get("step_step_1_validate_escalated_at"),
            "decided_at": now,
            "finalized_at": None
        },
        "validation_errors": [],
        "provenance": {
            "issue_key": "runtime_input",
            "decision": "human_response",
            "reviewer_comment": "human_response",
            "github_comment_url": "github_api_result",
            "label_status": "github_api_result"
        }
    }

    def finish():
        payload["timestamps"]["finalized_at"] = datetime.now(timezone.utc).isoformat()
        globals()["step_step_3b_reject_final_payload"] = payload
        print(json.dumps(payload, indent=2))

    # Guard: never act without a verifiable human REJECTED response.
    if dec != "REJECTED":
        payload["decision"] = "FAILED"
        payload["validation_errors"].append("Reject branch executed without a verifiable human REJECTED response. No external writes performed.")
        finish(); return
    if not token:
        payload["validation_errors"].append("GITHUB_TOKEN missing from environment.")
        finish(); return
    if not repo or not issue_key:
        payload["validation_errors"].append("Missing github_repository or issue_key.")
        finish(); return

    headers = {"Authorization": f"Bearer {token}", "Accept": "application/vnd.github.v3+json"}
    marker = f"Source-Key: {issue_key}"

    # Locate the issue by listing (search API lags on fresh private-repo content).
    matches = []
    try:
        for page in (1, 2, 3):
            r = requests.get(f"https://api.github.com/repos/{repo}/issues",
                             headers=headers,
                             params={"state": "all", "per_page": 100, "page": page},
                             timeout=30)
            if r.status_code != 200:
                payload["validation_errors"].append(f"GitHub list error ({r.status_code}): {r.text[:200]}")
                finish(); return
            batch = r.json()
            if not batch:
                break
            for it in batch:
                if "pull_request" in it:
                    continue
                if marker in (it.get("body") or ""):
                    matches.append(it)
    except Exception as e:
        payload["validation_errors"].append(f"GitHub list exception: {e}")
        finish(); return

    if len(matches) != 1:
        payload["validation_errors"].append(f"Issue lookup returned {len(matches)} matches for '{marker}'; expected exactly 1. No writes performed.")
        finish(); return

    issue_number = matches[0]["number"]
    comment_body = (
        "### \u274c Escalation Rejected\n\n"
        f"**Reviewer Comment:** {comment or 'No comment provided by reviewer.'}\n\n"
        f"**Policy Reason for Escalation:** {user_inputs.get('policy_reason')}\n\n"
        f"**Decision Timestamp:** {now}\n\n"
        "---\n"
        "*Provenance: [Reviewer Comment: human_response], [Policy Reason: runtime_input], [Timestamp: workflow_clock]*"
    )
    try:
        cr = requests.post(f"https://api.github.com/repos/{repo}/issues/{issue_number}/comments",
                           headers=headers, json={"body": comment_body}, timeout=30)
        if cr.status_code in (200, 201):
            payload["github_comment_status"] = "SUCCESS"
            payload["github_comment_url"] = cr.json().get("html_url")
        else:
            payload["validation_errors"].append(f"Comment error ({cr.status_code}): {cr.text[:200]}")
            finish(); return

        lr = requests.post(f"https://api.github.com/repos/{repo}/issues/{issue_number}/labels",
                           headers=headers, json={"labels": ["escalated"]}, timeout=30)
        payload["label_status"] = "SUCCESS" if lr.status_code in (200, 201) else f"FAILED ({lr.status_code})"
    except Exception as e:
        payload["validation_errors"].append(f"GitHub write exception: {e}")
        finish(); return

    if payload["github_comment_status"] == "SUCCESS" and payload["label_status"] == "SUCCESS":
        payload["run_status"] = "SUCCESS"
    finish()

step_3b_reject_run()

